#include <iostream>
#include <vector>
#include <queue>
#include <utility>
#include <cstring>
#include <climits>
using namespace std;

#include <math.h>

#define cost_t float
#define city_t uint16_t

// State Space Tree nodes
struct Node
{
  // stores edges of the state-space tree
  // help in tracing the path when the answer is found
  city_t *path;

  // stores the lower bound
  cost_t cost;

  // stores the current city number
  city_t vertex;

  // stores the total number of cities visited so far
  city_t level;

  // stores the reduced matrix
  cost_t reducedMatrix[];
};

// Function to allocate a new node `(i, j)` corresponds to visiting city `j`
// from city `i`
static Node *newNode(
        const cost_t *parentMatrix,
        city_t n_total,
        city_t *path,
        city_t level,
        city_t i,
        city_t j)
{
// printf("level %3u i %3u j %3u\n", level, i, j);
  size_t sizeof_reducedMatrix = n_total * n_total * sizeof(cost_t);
  Node *node = (Node *) malloc(sizeof(Node) + sizeof_reducedMatrix);

  // copy data from the parent node to the current node
  memcpy(node->reducedMatrix, parentMatrix, sizeof_reducedMatrix);

  // stores ancestors edges of the state-space tree
  node->path = (city_t *) malloc((level + 1) * sizeof(city_t));
  memcpy(node->path, path, level * sizeof(city_t));
  // add a current edge to the path
  node->path[level] = j;

  // Change all entries of row `i` and column `j` to `INFINITY`
  // skip for the root node
  if ( level != 0 )
  {
    for (city_t k = 0; k < n_total; k++)
    {
      // set outgoing edges for the city `i` to `INFINITY`
      node->reducedMatrix[i * n_total + k] = INFINITY;

      // set incoming edges to city `j` to `INFINITY`
      node->reducedMatrix[k * n_total + j] = INFINITY;
    }
  }

  // Set `(j, 0)` to `INFINITY`
  // here start node is 0
  node->reducedMatrix[j * n_total + 0] = INFINITY;

  // set number of cities visited so far
  node->level = level;

  // assign current city number
  node->vertex = j;

  // return node
  return node;
}

// Function to reduce each row so that there must be at least one zero in each row
static void rowReduction(cost_t *reducedMatrix, cost_t *row, city_t n_total)
{
  // initialize row array to `INFINITY`
  fill_n(row, n_total, INFINITY);

  // `row[i]` contains minimum in row `i`
  for (city_t i = 0; i < n_total; i++)
  {
    for (city_t j = 0; j < n_total; j++)
    {
      if (reducedMatrix[i * n_total + j] < row[i]) {
        row[i] = reducedMatrix[i * n_total + j];
      }
    }
  }

  // reduce the minimum value from each element in each row
  for (city_t i = 0; i < n_total; i++)
  {
    for (city_t j = 0; j < n_total; j++)
    {
      if (reducedMatrix[i * n_total + j] != INFINITY && row[i] != INFINITY) {
        reducedMatrix[i * n_total + j] -= row[i];
      }
    }
  }
}

// Function to reduce each column so that there must be at least one zero
// in each column
static void columnReduction(cost_t *reducedMatrix, cost_t *col, city_t n_total)
{
  // initialize all elements of array `col` with `INFINITY`
  fill_n(col, n_total, INFINITY);

  // `col[j]` contains minimum in col `j`
  for (city_t i = 0; i < n_total; i++)
  {
    for (city_t j = 0; j < n_total; j++)
    {
      if (reducedMatrix[i * n_total + j] < col[j]) {
        col[j] = reducedMatrix[i * n_total + j];
      }
    }
  }

  // reduce the minimum value from each element in each column
  for (city_t i = 0; i < n_total; i++)
  {
    for (city_t j = 0; j < n_total; j++)
    {
      if (reducedMatrix[i * n_total + j] != INFINITY && col[j] != INFINITY) {
        reducedMatrix[i * n_total + j] -= col[j];
      }
    }
  }
}

// Function to get the lower bound on the path starting at the current minimum node
static cost_t calculateCost(cost_t *reducedMatrix, city_t n_total)
{
  // initialize cost to 0
  cost_t cost = 0;

  // Row Reduction
  cost_t row[n_total];
  rowReduction(reducedMatrix, row, n_total);

  // Column Reduction
  cost_t col[n_total];
  columnReduction(reducedMatrix, col, n_total);

  // the total expected cost is the sum of all reductions
  for (city_t i = 0; i < n_total; i++)
  {
    if ( row[i] != INFINITY )
      cost += row[i];
    if ( col[i] != INFINITY )
      cost += col[i];
  }

  return cost;
}

// Function to print list of cities visited following least cost
static void printPath(city_t const *list, city_t n_total)
{
  for (city_t i = 0; i < n_total; i++) {
    if ( i != 0 )
      cout << ", ";
    cout << list[i] + 1;
  }
  cout << endl;
}

// Comparison object to be used to order the heap
struct comp
{
  bool operator()(const Node *lhs, const Node *rhs) const {
    return lhs->cost > rhs->cost;
  }
};

// Function to solve the traveling salesman problem using Branch and Bound
static cost_t solve(cost_t *costMatrix, city_t n_total)
{
  // Create a priority queue to store live nodes of the search tree
  priority_queue<Node *, vector<Node *>, comp> pq;

  // create a root node and calculate its cost.
  // The TSP starts from the first city, i.e., node 0
  Node *root = newNode(costMatrix, n_total, NULL, 0, -1, 0);

  // get the lower bound of the path starting at node 0
  root->cost = calculateCost(root->reducedMatrix, n_total);
  printf("level %3u i %3u j %3u cost %f\n", 0, -1, 0, root->cost);

  // Add root to the list of live nodes
  pq.push(root);

  // Finds a live node with the least cost, adds its children to the list of
  // live nodes, and finally deletes it from the list
  while (!pq.empty())
  {
    // Find a live node with the least estimated cost
    Node *min = pq.top();

    // The found node is deleted from the list of live nodes
    pq.pop();

    // `i` stores the current city number
    city_t i = min->vertex;

    // if all cities are visited
    if (min->level + 1 == n_total)
    {
      // print list of cities visited
      printPath(min->path, n_total);

      // return optimal cost
      cost_t ret = min->cost;
      free(min->path);
      free(min);
      while (!pq.empty())
      {
        min = pq.top();
        free(min->path);
        free(min);
        pq.pop();
      }
      return ret;
    }

    // do for each child of min
    // `(i, j)` forms an edge in a space tree
    for (city_t j = 0; j < n_total; j++)
    {
      if (min->reducedMatrix[i * n_total + j] != INFINITY)
      {
        // create a child node and calculate its cost
        Node *child = newNode(min->reducedMatrix, n_total, min->path, min->level + 1, i, j);

        /* Cost of the child =
         *  cost of the parent node +
         *  cost of the edge(i, j) +
         *  lower bound of the path starting at node j
         */

        child->cost = min->cost + min->reducedMatrix[i * n_total + j] + calculateCost(child->reducedMatrix, n_total);
        printf("level %3u i %3u j %3u cost %f\n", min->level + 1, i, j, child->cost);

        // Add a child to the list of live nodes
        pq.push(child);
      }
    }

    // free node as we have already stored edges `(i, j)` in vector.
    // So no need for a parent node while printing the solution.
    free(min->path);
    free(min);
  }

  /* never reached */
  return 0;
}

